CREATE TYPE "PredictionStatus" AS ENUM ('ACTIVE','EXPIRED','SUPERSEDED','INSUFFICIENT_EVIDENCE');
CREATE TYPE "PredictionConfidenceBand" AS ENUM ('LOW','MEDIUM','HIGH');
CREATE TYPE "PredictionFeedbackKind" AS ENUM ('ACCEPTED','IGNORED','REJECTED','CONVERTED','FALSE_POSITIVE','FALSE_NEGATIVE');
CREATE TABLE "PredictionStrategyVersion" ("id" TEXT NOT NULL,"businessId" TEXT NOT NULL,"name" TEXT NOT NULL,"version" TEXT NOT NULL,"configuration" JSONB,"isActive" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "PredictionStrategyVersion_pkey" PRIMARY KEY("id"),CONSTRAINT "PredictionStrategyVersion_businessId_fkey" FOREIGN KEY("businessId") REFERENCES "Business"("id") ON DELETE CASCADE);
CREATE UNIQUE INDEX "PredictionStrategyVersion_businessId_name_version_key" ON "PredictionStrategyVersion"("businessId","name","version");
CREATE INDEX "PredictionStrategyVersion_businessId_isActive_idx" ON "PredictionStrategyVersion"("businessId","isActive");
CREATE TABLE "Prediction" ("id" TEXT NOT NULL,"businessId" TEXT NOT NULL,"subjectId" TEXT NOT NULL,"predictionType" TEXT NOT NULL,"predictedValue" JSONB NOT NULL,"confidence" DECIMAL(5,4) NOT NULL,"confidenceBand" "PredictionConfidenceBand" NOT NULL,"publicExplanation" TEXT NOT NULL,"evidenceSummary" JSONB NOT NULL,"strategyVersionId" TEXT NOT NULL,"status" "PredictionStatus" NOT NULL DEFAULT 'ACTIVE',"validFrom" TIMESTAMP(3) NOT NULL,"generatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"expiresAt" TIMESTAMP(3) NOT NULL,"refreshedFromId" TEXT,CONSTRAINT "Prediction_pkey" PRIMARY KEY("id"),CONSTRAINT "Prediction_businessId_fkey" FOREIGN KEY("businessId") REFERENCES "Business"("id") ON DELETE CASCADE,CONSTRAINT "Prediction_businessId_subjectId_fkey" FOREIGN KEY("businessId","subjectId") REFERENCES "BusinessCustomer"("businessId","id") ON DELETE CASCADE,CONSTRAINT "Prediction_strategyVersionId_fkey" FOREIGN KEY("strategyVersionId") REFERENCES "PredictionStrategyVersion"("id") ON DELETE RESTRICT);
CREATE UNIQUE INDEX "Prediction_businessId_id_key" ON "Prediction"("businessId","id");
CREATE UNIQUE INDEX "Prediction_one_active_type_per_subject" ON "Prediction"("businessId","subjectId","predictionType") WHERE "status"='ACTIVE';
CREATE INDEX "Prediction_businessId_subjectId_status_expiresAt_idx" ON "Prediction"("businessId","subjectId","status","expiresAt");
CREATE INDEX "Prediction_businessId_predictionType_status_generatedAt_idx" ON "Prediction"("businessId","predictionType","status","generatedAt");
CREATE INDEX "Prediction_expiresAt_status_idx" ON "Prediction"("expiresAt","status");
CREATE TABLE "PredictionSignal" ("id" TEXT NOT NULL,"predictionId" TEXT NOT NULL,"source" TEXT NOT NULL,"referenceId" TEXT,"featureName" TEXT NOT NULL,"featureValue" JSONB NOT NULL,"occurredAt" TIMESTAMP(3) NOT NULL,"freshness" DECIMAL(5,4) NOT NULL,"reliability" DECIMAL(5,4) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "PredictionSignal_pkey" PRIMARY KEY("id"),CONSTRAINT "PredictionSignal_predictionId_fkey" FOREIGN KEY("predictionId") REFERENCES "Prediction"("id") ON DELETE CASCADE);
CREATE INDEX "PredictionSignal_predictionId_source_idx" ON "PredictionSignal"("predictionId","source");
CREATE TABLE "PredictionEvidence" ("id" TEXT NOT NULL,"predictionId" TEXT NOT NULL,"kind" TEXT NOT NULL,"summary" TEXT NOT NULL,"weight" DECIMAL(5,4) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "PredictionEvidence_pkey" PRIMARY KEY("id"),CONSTRAINT "PredictionEvidence_predictionId_fkey" FOREIGN KEY("predictionId") REFERENCES "Prediction"("id") ON DELETE CASCADE);
CREATE INDEX "PredictionEvidence_predictionId_idx" ON "PredictionEvidence"("predictionId");
CREATE TABLE "PredictionFeedback" ("id" TEXT NOT NULL,"businessId" TEXT NOT NULL,"predictionId" TEXT NOT NULL,"actorId" TEXT NOT NULL,"kind" "PredictionFeedbackKind" NOT NULL,"metadata" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "PredictionFeedback_pkey" PRIMARY KEY("id"),CONSTRAINT "PredictionFeedback_businessId_predictionId_fkey" FOREIGN KEY("businessId","predictionId") REFERENCES "Prediction"("businessId","id") ON DELETE CASCADE);
CREATE UNIQUE INDEX "PredictionFeedback_predictionId_actorId_kind_key" ON "PredictionFeedback"("predictionId","actorId","kind");CREATE INDEX "PredictionFeedback_businessId_createdAt_idx" ON "PredictionFeedback"("businessId","createdAt");
CREATE TABLE "PredictionOutcome" ("id" TEXT NOT NULL,"businessId" TEXT NOT NULL,"predictionId" TEXT NOT NULL,"outcome" TEXT NOT NULL,"actualValue" JSONB,"occurredAt" TIMESTAMP(3) NOT NULL,"recordedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "PredictionOutcome_pkey" PRIMARY KEY("id"),CONSTRAINT "PredictionOutcome_businessId_predictionId_fkey" FOREIGN KEY("businessId","predictionId") REFERENCES "Prediction"("businessId","id") ON DELETE CASCADE);
CREATE UNIQUE INDEX "PredictionOutcome_predictionId_key" ON "PredictionOutcome"("predictionId");CREATE INDEX "PredictionOutcome_businessId_occurredAt_idx" ON "PredictionOutcome"("businessId","occurredAt");
CREATE TABLE "PredictionEvent" ("id" TEXT NOT NULL,"businessId" TEXT NOT NULL,"predictionId" TEXT,"type" TEXT NOT NULL,"version" INTEGER NOT NULL DEFAULT 1,"payload" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "PredictionEvent_pkey" PRIMARY KEY("id"),CONSTRAINT "PredictionEvent_businessId_fkey" FOREIGN KEY("businessId") REFERENCES "Business"("id") ON DELETE CASCADE);
CREATE INDEX "PredictionEvent_businessId_type_createdAt_idx" ON "PredictionEvent"("businessId","type","createdAt");CREATE INDEX "PredictionEvent_businessId_predictionId_createdAt_idx" ON "PredictionEvent"("businessId","predictionId","createdAt");
